result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "selector.py", "content": """"A small CSS selector engine.

Parses a useful subset of CSS selectors into an AST, and matches ASTs
against a toy DOM where an element is a dict:

    {
        "tag": str,               # tag name, lowercase, e.g. "div"
        "attrs": dict[str, str],  # attribute name -> value (no value => "")
        "children": list[dict],   # child elements in document order
        "parent": dict | None,    # parent element or None for root
    }

Supported syntax:
    type        div
    universal   *
    id          #main
    class       .note
    [attr]      [href]
    [attr=v]    [href="http://x"]  (quoted or unquoted)
    [attr^=v]   prefix match
    [attr$=v]   suffix match
    compounds   div.note#x[href^="ab"]
    combinators descendant (whitespace), child `>`, adjacent sibling `+`
    groups      sel1, sel2, ...  (comma-separated selector lists)

AST shape (each node is a dict with a "type" key):

    {"type": "list", "selectors": [complex, ...]}
    {"type": "complex", "combinators": [...], "compound": CompoundSelector}
        A complex selector is stored right-to-left as a chain:
        "div > p + span" == span (+) p (>) div. Concretely:
            "subject"      : CompoundSelector that must match the element
            "rest"         : Complex | None, the part to the left
            "combinator"   : one of " ", ">", "+", how rest relates to subject
    {"type": "compound", "parts": [SimpleSelector, ...]}
        All parts must match the same element.
    Simple selectors (all with "type"):
        {"type": "type", "name": str}
        {"type": "universal"}
        {"type": "id", "value": str}
        {"type": "class", "name": str}
        {"type": "attr", "name": str,
         "op": None | "=" | "^=" | "$=", "value": str | None}

Malformed input raises :class:`SelectorError`, which carries ``pos`` -- the
0-based character position where parsing failed -- and a human message.
"""


class SelectorError(ValueError):
    """Raised for malformed selectors.

    Attributes:
        pos: 0-based character position in the selector string where the
             error was detected.
        msg: description of the problem.
    """

    def __init__(self, msg: str, pos: int):
        super().__init__(f"{msg} at position {pos}")
        self.msg = msg
        self.pos = pos


_IDENT_START = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_")
_IDENT_CHARS = _IDENT_START | set("0123456789-")


class _Parser:
    def __init__(self, text: str):
        self.s = text
        self.i = 0

    # -- low-level helpers ------------------------------------------------

    def error(self, msg: str, pos: int | None = None) -> SelectorError:
        return SelectorError(msg, self.i if pos is None else pos)

    def peek(self) -> str:
        return self.s[self.i] if self.i < len(self.s) else ""

    def skip_ws(self) -> bool:
        """Skip whitespace; return True if any was skipped."""
        start = self.i
        while self.peek() in (" ", "\t", "\n", "\r", "\f"):
            self.i += 1
        return self.i > start

    def ident(self) -> str:
        start = self.i
        if self.peek() not in _IDENT_START:
            raise self.error("expected identifier")
        while self.peek() in _IDENT_CHARS:
            self.i += 1
        return self.s[start:self.i]

    def expect(self, ch: str) -> None:
        if self.peek() != ch:
            raise self.error(f"expected {ch!r}")

    # -- grammar ----------------------------------------------------------

    def parse(self) -> dict:
        selectors = [self.complex_selector()]
        while True:
            self.skip_ws()
            if self.peek() == ",":
                self.i += 1
                self.skip_ws()
                if self.peek() == "":
                    raise self.error("expected selector after ','")
                selectors.append(self.complex_selector())
            elif self.peek() == "":
                break
            else:
                raise self.error(f"unexpected character {self.peek()!r}")
        if len(selectors) == 1:
            return selectors[0]
        return {"type": "list", "selectors": selectors}

    def complex_selector(self) -> dict:
        """Parse one complex selector; returns right-to-left chain."""
        subject = self.compound_selector()
        node = {"type": "complex", "subject": subject, "rest": None, "combinator": None}
        while True:
            had_ws = self.skip_ws()
            ch = self.peek()
            if ch in (">", "+"):
                combinator = ch
                self.i += 1
                self.skip_ws()
            elif ch in ("", ",", ")") or ch == ",":
                break
            elif had_ws and ch and (ch in _IDENT_START or ch in "*.[#"):
                combinator = " "
            else:
                break
            nxt = self.compound_selector()
            node = {
                "type": "complex",
                "subject": nxt,
                "rest": node,
                "combinator": combinator,
            }
        return node

    def compound_selector(self) -> dict:
        parts = []
        ch = self.peek()
        if ch == "*":
            self.i += 1
            parts.append({"type": "universal"})
        elif ch in _IDENT_START:
            parts.append({"type": "type", "name": self.ident()})
        while True:
            ch = self.peek()
            if ch == "#":
                self.i += 1
                parts.append({"type": "id", "value": self._hash_name()})
            elif ch == ".":
                self.i += 1
                parts.append({"type": "class", "name": self._class_name()})
            elif ch == "[":
                parts.append(self.attribute())
            else:
                break
        if not parts:
            raise self.error("expected selector")
        return {"type": "compound", "parts": parts}

    def _after_marker(self, what: str) -> str:
        """Consume the char after '#'/'.' and require it starts an identifier."""
        if self.peek() not in _IDENT_START:
            raise self.error(f"expected {what}")
        return self.ident()

    def _hash_name(self) -> str:
        return self._after_marker("id name")

    def _class_name(self) -> str:
        return self._after_marker("class name")

    def attribute(self) -> dict:
        start = self.i
        self.expect("[")
        self.i += 1
        self.skip_ws()
        if self.peek() not in _IDENT_START:
            raise self.error("expected attribute name", self.i)
        name = self.ident()
        self.skip_ws()
        op = None
        value = None
        ch = self.peek()
        if ch == "]":
            self.i += 1
            return {"type": "attr", "name": name, "op": op, "value": value}
        if ch in ("=", "^", "$"):
            if ch == "=":
                op = "="
                self.i += 1
            else:
                if self.i + 1 >= len(self.s) or self.s[self.i + 1] != "=":
                    raise self.error(f"expected '^=' or '$=' at position {start}", self.i)
                op = ch + "="
                self.i += 2
        else:
            raise self.error(
                f"expected ']', '=', '^=' or '$=', got {ch!r}"
            )
        self.skip_ws()
        vch = self.peek()
        if vch == "" or vch in ("]", ",", ">", "+"):
            raise self.error("expected attribute value")
        if vch in ('"', "'"):
            quote = vch
            self.i += 1
            vstart = self.i
            while self.peek() != quote:
                if self.peek() == "":
                    raise self.error("unterminated string")
                self.i += 1
            value = self.s[vstart:self.i]
            self.i += 1  # closing quote
        else:
            vstart = self.i
            while self.peek() and self.peek() not in ("]", " ", "\t", "\n", "\r", "\f"):
                self.i += 1
            value = self.s[vstart:self.i]
            if value == "":
                raise self.error("expected attribute value")
        self.skip_ws()
        if self.peek() != "]":
            raise self.error("expected ']'")
        self.i += 1
        return {"type": "attr", "name": name, "op": op, "value": value}


def parse(selector: str) -> dict:
    """Parse a CSS selector string into an AST (see module docstring)."""
    p = _Parser(selector)
    ast = p.parse()
    return ast


# -- matching ---------------------------------------------------------------


def _matches_simple(simple: dict, el: dict) -> bool:
    t = simple["type"]
    attrs = el.get("attrs", {})
    if t == "universal":
        return True
    if t == "type":
        return el.get("tag") == simple["name"]
    if t == "id":
        return attrs.get("id") == simple["value"]
    if t == "class":
        classes = attrs.get("class", "").split()
        return simple["name"] in classes
    if t == "attr":
        if simple["op"] is None:
            return simple["name"] in attrs
        val = attrs.get(simple["name"])
        if val is None:
            return False
        want = simple["value"]
        op = simple["op"]
        if op == "=":
            return val == want
        if op == "^=":
            return want != "" and val.startswith(want)
        if op == "$=":
            return want != "" and val.endswith(want)
        raise SelectorError(f"unknown attribute operator {op!r}", 0)
    raise SelectorError(f"unknown simple selector type {t!r}", 0)


def _matches_compound(compound: dict, el: dict) -> bool:
    return all(_matches_simple(p, el) for p in compound["parts"])


def _matches_complex(node: dict, el: dict) -> bool:
    if not _matches_compound(node["subject"], el):
        return False
    rest = node["rest"]
    if rest is None:
        return True
    combinator = node["combinator"]
    parent = el.get("parent")
    if combinator == ">":
        return parent is not None and _matches_complex(rest, parent)
    if combinator == "+":
        prev = _previous_element_sibling(el)
        return prev is not None and _matches_complex(rest, prev)
    if combinator == " ":
        anc = parent
        while anc is not None:
            if _matches_complex(rest, anc):
                return True
            anc = anc.get("parent")
        return False
    raise SelectorError(f"unknown combinator {combinator!r}", 0)


def _previous_element_sibling(el: dict) -> dict | None:
    parent = el.get("parent")
    if parent is None:
        return None
    siblings = parent.get("children", [])
    try:
        idx = siblings.index(el)
    except ValueError:
        return None
    return siblings[idx - 1] if idx > 0 else None


def matches(ast: dict, element: dict) -> bool:
    """Return True if ``element`` matches the parsed selector ``ast``."""
    t = ast["type"]
    if t == "list":
        return any(matches(sel, element) for sel in ast["selectors"])
    if t == "complex":
        return _matches_complex(ast, element)
    raise SelectorError(f"not a valid selector AST node: {t!r}", 0)
