result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test_selector.py", "content": "import pytest

from selector import SelectorError, matches, parse


def el(tag, attrs=None, children=None, parent=None):
    node = {
        "tag": tag,
        "attrs": attrs or {},
        "children": children or [],
        "parent": parent,
    }
    for child in node["children"]:
        child["parent"] = node
    return node


# --------------------------------------------------------------------------
# Fixture tree:
#
# <div id="main" class="container">
#     <p class="note">first</p>
#     <span data-x="abc">s1</span>
#     <p>second</p>
# </div>
# <ul id="list">
#     <li data-x="ab1">a</li>
#     <li data-x="ab2">b</li>
#     <li data-x="zz">c</li>
# </ul>
# <a href="https://example.com/page.html">link</a>
# --------------------------------------------------------------------------


@pytest.fixture
def tree():
    p_note = el("p", {"class": "note"})
    span = el("span", {"data-x": "abc"})
    p_plain = el("p")
    div = el("div", {"id": "main", "class": "container"}, [p_note, span, p_plain])

    li1 = el("li", {"data-x": "ab1"})
    li2 = el("li", {"data-x": "ab2"})
    li3 = el("li", {"data-x": "zz"})
    ul = el("ul", {"id": "list"}, [li1, li2, li3])

    a = el("a", {"href": "https://example.com/page.html"})

    root = el("body", {}, [div, ul, a])
    return {
        "root": root,
        "div": div,
        "p_note": p_note,
        "span": span,
        "p_plain": p_plain,
        "ul": ul,
        "li1": li1,
        "li2": li2,
        "li3": li3,
        "a": a,
    }


ALL = [
    "root", "div", "p_note", "span", "p_plain",
    "ul", "li1", "li2", "li3", "a",
]


def matched(tree, selector):
    ast = parse(selector)
    return {name for name in ALL if matches(ast, tree[name])}


# -- simple selectors -------------------------------------------------------


def test_type_selector(tree):
    assert matched(tree, "p") == {"p_note", "p_plain"}


def test_universal_selector(tree):
    assert "*" == set(ALL)  # sanity: universal covers every element


def test_id_selector(tree):
    assert matched(tree, "#main") == {"div"}
    assert matched(tree, "#list") == {"ul"}
    assert matched(tree, "#nope") == set()


def test_class_selector(tree):
    assert matched(tree, ".note") == {"p_note"}
    assert matched(tree, ".container") == {"div"}


def test_attr_presence(tree):
    assert matched(tree, "[id]") == {"div", "ul"}
    assert matched(tree, "[data-x]") == {"span", "li1", "li2", "li3"}


def test_attr_equals(tree):
    assert matched(tree, "[data-x=abc]") == {"span"}
    # quoted values work too
    assert matched(tree, '[href="https://example.com/page.html"]') == {"a"}


def test_attr_starts_with(tree):
    assert matched(tree, "[data-x^=ab]") == {"li1", "li2"}


def test_attr_ends_with(tree):
    assert matched(tree, "[href$=.html]") == {"a"}
    assert matched(tree, '[href$=".com"]') == set()


def test_attr_no_match_without_attr(tree):
    assert matched(tree, "[title=x]") == set()


# -- compound selectors ------------------------------------------------------


def test_compound_tag_class_id(tree):
    assert matched(tree, "div.container#main") == {"div"}
    assert matched(tree, "p.note") == {"p_note"}
    assert matched(tree, "p#main") == set()
    assert matched(tree, "ul#list[data-x^=ab]") == set()  # ul lacks data-x


def test_compound_with_attributes(tree):
    assert matched(tree, "li[data-x][data-x$=1]") == {"li1"}


# -- combinators -------------------------------------------------------------


def test_descendant_combinator(tree):
    assert matched(tree, "div .note") == {"p_note"}
    assert matched(tree, "body li") == {"li1", "li2", "li3"}
    assert matched(tree, "ul li") == {"li1", "li2", "li3"}
    assert matched(tree, "div li") == set()


def test_child_combinator(tree):
    assert matched(tree, "div > p") == {"p_note", "p_plain"}
    assert matched(tree, "body > li") == set()
    assert matched(tree, "body > ul > li[data-x=zz]") == {"li3"}


def test_adjacent_sibling_combinator(tree):
    assert matched(tree, "p + span") == {"span"}
    assert matched(tree, ".note + *") == {"span"}  # note + next element
    assert matched(tree, "span + p") == {"p_plain"}


def test_chained_combinators_required_by_spec(tree):
    assert matched(tree, "div > p.note + span") == {"span"}
    # negative controls: subject doesn't fit the chain elsewhere
    assert matched(tree, "ul li[data-x^=ab]") == {"li1", "li2"}
    assert matched(tree, "ul > li[data-x^=ab] + li") == {"li2"}


def test_deep_chain(tree):
    assert matched(tree, "body > div > p:first-child-ish")  # placeholder guard


# The test above intentionally uses an invalid selector to prove errors raise;
# rewrite it properly here:


def test_invalid_selectors_raise_with_position():
    cases = [
        ("", 0),
        ("> p", 0),
        ("div >", 5),
        ("div ~ p", 4),          # unsupported combinator
        ("div..note", 4),
        ("#", 1),
        (".", 1),
        ("[attr", 5),
        ("[attr=]", 6),
        ('[attr="unterminated]', 6),
        ("div,", 4),
        ("[attr~=x]", 5),
        ("123", 0),
    ]
    for sel, expected_pos in cases:
        with pytest.raises(SelectorError) as excinfo:
            parse(sel)
        assert excinfo.value.pos == expected_pos, (
            f"{sel!r}: pos {excinfo.value.pos} != {expected_pos}"
        )


# -- selector lists -----------------------------------------------------------


def test_selector_list(tree):
    assert matched(tree, "p, span") == {"p_note", "p_plain", "span"}
    assert matched(tree, "#main, #list") == {"div", "ul"}
    assert matched(tree, "div > p, ul li[data-x^=ab], [href$=.html]") == {
        "p_note", "p_plain", "li1", "li2", "a",
    }


def test_matches_takes_ast_not_string(tree):
    ast = parse("div > p.note + span")
    assert matches(ast, tree["span"]) is True
    assert matches(ast, tree["p_note"]) is False


def test_error_is_valueerror_subclass():
    with pytest.raises(ValueError):
        parse("!!")
